update public.question_bank
set question_text = 'Uma empresa alimentícia realiza as suas entregas interestaduais por meio de um caminhão de carga. Em 10/12/2024, a empresa foi notificada porque o caminhão transportava mais do que o limite local permitido. O prazo para pagamento da multa era de 30 dias e não havia possibilidade de recorrer. Ao realizar sua Demonstração do Resultado anual, referente a 2024, a empresa decidiu esperar até a finalização do prazo para pagamento da multa para reconhecer a despesa. Ao analisar o fato, um perito constatou que não foi atendida a característica qualitativa da informação contábil-financeira denominada:',
    explanation = 'A alternativa correta é B — tempestividade. A multa já era conhecida em 10/12/2024, a obrigação era exigível e não havia possibilidade de recurso. Pelo regime de competência, a despesa deveria ser reconhecida em 2024, independentemente de o pagamento ocorrer em janeiro de 2025. Esperar o vencimento para registrar a despesa atrasa a informação e pode levar o usuário das demonstrações a tomar decisões com dados incompletos. Isso viola a tempestividade, que exige que a informação contábil esteja disponível no momento em que ainda pode influenciar decisões. Não se trata de neutralidade, continuidade, materialidade ou compreensibilidade. Dica: quando o enunciado disser que o fato já ocorreu, mas o registro foi adiado sem justificativa, procure a característica tempestividade.',
    content_status = 'active'
where id = 'a90f4162-5626-4663-9946-0bbd7bf2d2f8';
